/**
 * Virtualised issue list; hides row actions the actor may not perform.
 *
 * Must call (do not reimplement): can
 */
import { EmptyState } from "@/components/ui/empty-state";
import {
  Table,
  TableBody,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import type { IssueId } from "@/types/common";
import type { IssueWithRelations } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { IssueRow } from "./issue-row";

export type IssueListProps = {
  issues: readonly IssueWithRelations[];
  actor: Actor;
  emptyLabel?: string;
  onArchive?: (issueId: IssueId) => void;
  /** Assignee lookup for the rows; the page joins users once, not per row. */
  users?: Readonly<Record<string, User>>;
};

const COLUMNS: readonly string[] = [
  "#",
  "Title",
  "Status",
  "Priority",
  "Assignee",
  "Due",
  "",
];

export function IssueList(props: IssueListProps): ReactElement | null {
  const { issues, actor, emptyLabel, onArchive, users = {} } = props;

  // One coarse check for the whole list: an actor who cannot read issues at
  // all sees the empty state rather than a table of hidden rows.
  if (!can(actor, "issue:read", organizationResource(actor.orgId))) {
    return (
      <EmptyState
        title="No access"
        description="Your role does not include issue access in this organization."
      />
    );
  }

  if (issues.length === 0) {
    return (
      <EmptyState
        title={emptyLabel ?? "No issues match this filter"}
        description="Adjust the filters or create the first issue."
      />
    );
  }

  // Live rows first; archived ones stay visible but sink to the bottom.
  const ordered = [...issues].sort((a, b) => {
    const archivedDelta =
      Number(isArchived(a.issue)) - Number(isArchived(b.issue));
    if (archivedDelta !== 0) return archivedDelta;
    return b.issue.updatedAt.localeCompare(a.issue.updatedAt);
  });

  return (
    <Table caption="Issues">
      <TableHead>
        <TableRow>
          {COLUMNS.map((column, index) => (
            <TableHeaderCell key={column.length === 0 ? `col-${index}` : column}>
              {column}
            </TableHeaderCell>
          ))}
        </TableRow>
      </TableHead>
      <TableBody>
        {ordered.map(({ issue }) => (
          <IssueRow
            key={issue.id}
            issue={issue}
            actor={actor}
            assignee={
              issue.assigneeId === null ? null : users[issue.assigneeId] ?? null
            }
            {...(onArchive !== undefined ? { onArchive } : {})}
          />
        ))}
      </TableBody>
    </Table>
  );
}
"use client";

/**
 * Drag-and-drop board; renders nothing unless the `kanban_board` flag is on.
 *
 * Must call (do not reimplement): isEnabled, can
 */
import { useState, useTransition } from "react";
import { EmptyState } from "@/components/ui/empty-state";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import type { MoveIssueInput } from "@/schemas/issue";
import type { ActionResult } from "@/types/api";
import type { IssueId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Issue, IssueBoardColumn, IssueStatus } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { moveIssueInColumns, orderColumns } from "./board-model";
import { KanbanColumn } from "./kanban-column";

export type KanbanBoardProps = {
  columns: readonly IssueBoardColumn[];
  actor: Actor;
  flags: FeatureFlagSnapshot;
  onMove: (input: MoveIssueInput) => Promise<ActionResult<Issue>>;
  /** Assignee lookup passed straight through to the cards. */
  users?: Readonly<Record<string, User>>;
};

export function KanbanBoard(props: KanbanBoardProps): ReactElement | null {
  const { columns, actor, flags, onMove, users } = props;

  // The snapshot the layout serialised is the fast path; `isEnabled()` is the
  // fallback for a snapshot that predates the flag.
  const boardEnabled =
    flags.kanban_board === true ||
    isEnabled("kanban_board", {
      orgId: actor.orgId,
      userId: actor.userId,
      plan: "free",
      role: actor.role,
    });

  const [local, setLocal] = useState<readonly IssueBoardColumn[] | null>(null);
  const [pending, startTransition] = useTransition();

  if (!boardEnabled) return null;

  const mayMove = can(actor, "issue:update", organizationResource(actor.orgId));
  const rendered = orderColumns(local ?? columns);

  if (rendered.every((column) => column.issues.length === 0)) {
    return (
      <EmptyState
        title="This board is empty"
        description="Create an issue to see it here."
      />
    );
  }

  function handleDrop(
    toStatus: IssueStatus,
    issueId: IssueId,
    toIndex: number,
  ): void {
    if (!mayMove) return;
    // Land the card immediately, then let the action reconcile; on failure the
    // local override is dropped and the server columns win again.
    const optimistic = moveIssueInColumns(rendered, issueId, toStatus, toIndex);
    setLocal(optimistic);

    startTransition(async () => {
      const result = await onMove({
        orgId: actor.orgId,
        issueId,
        toStatus,
        toIndex,
      });
      if (!result.ok) setLocal(null);
    });
  }

  return (
    <div
      className="kanban-board flex gap-3 overflow-x-auto"
      aria-busy={pending}
    >
      {rendered.map((column) => (
        <KanbanColumn
          key={column.status}
          column={column}
          actor={actor}
          onDrop={(issueId, toIndex) =>
            handleDrop(column.status, issueId, toIndex)
          }
          {...(users !== undefined ? { users } : {})}
        />
      ))}
    </div>
  );
}
"use client";

/**
 * One status column with a drop target.
 *
 * Must call (do not reimplement): can
 */
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/cn";
import { humanizeStatus } from "@/lib/format";
import { can } from "@/lib/permissions";
import type { IssueId } from "@/types/common";
import type { IssueBoardColumn } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { issueResource } from "../permission/resources";
import { STATUS_TONE } from "../issue/issue-tone";
import { KANBAN_DRAG_TYPE, KanbanCard } from "./kanban-card";

export type KanbanColumnProps = {
  column: IssueBoardColumn;
  actor: Actor;
  onDrop: (issueId: IssueId, toIndex: number) => void;
  /** Assignee lookup so cards do not each re-join the member list. */
  users?: Readonly<Record<string, User>>;
};

export function KanbanColumn(props: KanbanColumnProps): ReactElement | null {
  const { column, actor, onDrop, users = {} } = props;

  return (
    <section
      className={cn(
        "kanban-column flex w-64 shrink-0 flex-col gap-2 rounded bg-neutral-50 p-2",
      )}
      onDragOver={(event) => event.preventDefault()}
      onDrop={(event) => {
        event.preventDefault();
        const issueId = event.dataTransfer.getData(KANBAN_DRAG_TYPE);
        if (issueId.length === 0) return;
        onDrop(issueId as IssueId, column.issues.length);
      }}
    >
      <header className="flex items-center justify-between">
        <Badge tone={STATUS_TONE[column.status]} size="sm">
          {humanizeStatus(column.status)}
        </Badge>
        <span className="text-xs text-neutral-500">{column.total}</span>
      </header>

      {column.issues.map((issue) => (
        <KanbanCard
          key={issue.id}
          issue={issue}
          assignee={
            issue.assigneeId === null ? null : users[issue.assigneeId] ?? null
          }
          // Dragging is a status change: only actors who may update this
          // particular issue get a grab cursor.
          draggable={can(actor, "issue:update", issueResource(issue))}
        />
      ))}

      {column.issues.length === 0 ? (
        <p className="px-1 py-4 text-center text-xs text-neutral-400">
          Nothing here
        </p>
      ) : null}
    </section>
  );
}

