/**
 * Timestamp helpers: ISO round-tripping, relative formatting, due-date and
 * digest-window arithmetic.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 */
import type { IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
 * issue cards and comment headers all use.
 */
export function formatRelative(
  value: IsoTimestamp,
  reference: Date = new Date(),
): string {
  const deltaMs = parseIso(value).getTime() - reference.getTime();
  const past = deltaMs < 0;
  const abs = Math.abs(deltaMs);

  const phrase = ((): string => {
    if (abs < MINUTE_MS) return "just now";
    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
  })();

  if (phrase === "just now") return phrase;
  return past ? `${phrase} ago` : `in ${phrase}`;
}

/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

/** Validate through Intl so repository writes and date helpers agree. */
export function assertTimeZone(timeZone: string): void {
  new Intl.DateTimeFormat("en", { timeZone }).format(0);
}

function localParts(reference: Date, timeZone: string): number[] {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone, year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23",
  }).formatToParts(reference);
  return ["year", "month", "day", "hour", "minute", "second"].map(
    (name) => Number(parts.find((part) => part.type === name)!.value),
  );
}

export function localDate(value: IsoTimestamp, timeZone: string): string {
  const [year, month, day] = localParts(parseIso(value), timeZone);
  return `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

/** Calendar arithmetic uses UTC only as a container for calendar fields. */
function calendarDate(day: string, offset: number): string {
  const date = new Date(`${day}T12:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + offset);
  return date.toISOString().slice(0, 10);
}

/**
 * Resolve wall time using offsets on both sides of a possible transition.
 * Repeated times use the first occurrence; skipped times move forward by
 * the size of the gap, matching Date's compatible disambiguation.
 */
function localTime(day: string, hour: number, timeZone: string, atOrBefore?: Date): Date {
  const wall = Date.parse(`${day}T${String(hour).padStart(2, "0")}:00:00.000Z`);
  const offsets = new Set<number>();
  for (const delta of [-2, -1, 0, 1, 2]) {
    const sample = wall + delta * DAY_MS;
    const [y, m, d, h, min, sec] = localParts(new Date(sample), timeZone);
    offsets.add(Date.UTC(y, m - 1, d, h, min, sec) - sample);
  }
  const candidates = [...offsets].map((offset) => wall - offset).sort((a, b) => a - b);
  const exact = candidates.filter((candidate) => {
    const [y, m, d, h, min, sec] = localParts(new Date(candidate), timeZone);
    return Date.UTC(y, m - 1, d, h, min, sec) === wall;
  });
  const passed = atOrBefore === undefined ? [] : exact.filter((value) => value <= atOrBefore.getTime());
  return new Date(passed.at(-1) ?? exact[0] ?? candidates[candidates.length - 1]);
}

/** Convert a calendar date chosen in a workspace to its midnight instant. */
export function fromLocalDate(day: string, timeZone = "UTC"): IsoTimestamp {
  return toIsoTimestamp(localTime(day, 0, timeZone));
}

export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return localDayOffset(reference, timeZone, 0);
}

/** Midnight a number of calendar days from the reference's local date. */
export function localDayOffset(reference: Date, timeZone: string, days: number): IsoTimestamp {
  const day = calendarDate(localDate(toIsoTimestamp(reference), timeZone), days);
  return toIsoTimestamp(localTime(day, 0, timeZone));
}

/** A due day is overdue only after that local calendar day has ended. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/** Window between the configured hour on consecutive local calendar days. */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }
  let day = localDate(toIsoTimestamp(reference), timeZone);
  let end = localTime(day, digestHourUtc, timeZone, reference);
  if (end.getTime() > reference.getTime()) {
    day = calendarDate(day, -1);
    end = localTime(day, digestHourUtc, timeZone, reference);
  }
  return {
    start: toIsoTimestamp(localTime(calendarDate(day, -1), digestHourUtc, timeZone)),
    end: toIsoTimestamp(end),
  };
}
